def backfill_site_campaigns(apps, schema_editor):
    """Attach legacy sites to the campaign of their earliest assignment.

    Sites are now configured inside one campaign. Existing sites predate that
    relation; using their first non-null assignment campaign preserves the
    visible campaign scope without creating duplicate sites.
    """
    DistributionSite = apps.get_model("corn", "DistributionSite")
    DistributorAssignment = apps.get_model("corn", "DistributorAssignment")
    for site in DistributionSite.objects.filter(campaign__isnull=True).iterator():
        campaign_id = (
            DistributorAssignment.objects.filter(
                site_id=site.id, campaign_id__isnull=False
            )
            .order_by("created_at")
            .values_list("campaign_id", flat=True)
            .first()
        )
        if campaign_id is not None:
            site.campaign_id = campaign_id
            site.save(update_fields=["campaign"])


